impl NetworkPolicy {
    pub fn allows(&self, destination: &str) -> bool {
        match self {
            NetworkPolicy::DenyAll => false,
            NetworkPolicy::AllowProviders { endpoints } => {
                endpoints.iter().any(|rule| destination.starts_with(rule))
            }
            NetworkPolicy::AllowConfigured { endpoints, domains } => endpoints
                .iter()
                .chain(domains.iter())
                .any(|rule| destination.starts_with(rule)),
        }
    }
}

